// ============================================================
// GET /auth/callback — where every auth link lands:
//   ?type=signup_confirm  email confirmation after sign-up (SMTP on)
//   ?type=recovery        password reset (emailed, or generated by an
//                         owner / the CLI when SMTP is off)
//   ?type=email_change    confirm a new email address (SMTP on)
//
// Flow:
//   1. parse `type` + `token`; anything else → /login?error=link_invalid
//   2. consume the single-use token and mint a session
//   3. 303 to the validated `next` path (/dashboard, /reset-password,
//      /join/<t>) with the session cookie set
//      expired / already used → /login?error=link_expired
//
// `Location` is emitted as a relative path on purpose — see
// `relativeRedirect` for the reverse-proxy reasoning.
// ============================================================

import { loginFailurePath, parseEmailLink, relativeRedirect, safeNextPath } from '@/lib/auth/callback';
import { AuthFailure, consumeLink } from '@/lib/auth/service';
import { SESSION_COOKIE, sessionCookieOptions } from '@/lib/auth/session';
import { getClientIp } from '@/lib/http/request';
import { checkRateLimit } from '@/lib/rate-limit';

// Session exchange is per-request by definition; never prerender.
export const dynamic = 'force-dynamic';
export const runtime = 'nodejs';

function serializeCookie(name: string, value: string, opts: ReturnType<typeof sessionCookieOptions>): string {
  const parts = [`${name}=${value}`, `Path=${opts.path}`, `Expires=${opts.expires.toUTCString()}`, 'HttpOnly', 'SameSite=Lax'];
  if (opts.secure) parts.push('Secure');
  return parts.join('; ');
}

export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const link = parseEmailLink(searchParams);
  const fallback = link?.type === 'recovery' ? '/reset-password' : undefined;
  const next = safeNextPath(searchParams.get('next'), fallback);

  if (!link) {
    return relativeRedirect(loginFailurePath('link_invalid'));
  }
  if (!checkRateLimit(`auth-callback:${getClientIp(request)}`, { limit: 20, windowMs: 60_000 }).success) {
    return relativeRedirect(loginFailurePath('link_invalid'));
  }

  try {
    const session = await consumeLink(link.type, link.token, {
      userAgent: request.headers.get('user-agent'),
      ip: getClientIp(request),
    });
    const res = relativeRedirect(next);
    res.headers.append(
      'Set-Cookie',
      serializeCookie(SESSION_COOKIE, session.token, sessionCookieOptions(session.expiresAt)),
    );
    return res;
  } catch (err) {
    if (err instanceof AuthFailure) {
      return relativeRedirect(loginFailurePath('link_expired'));
    }
    console.error('[GET /auth/callback] failed:', err);
    return relativeRedirect(loginFailurePath('link_invalid'));
  }
}
